    if isinstance(b, (int, float)) and isinstance(c, (int, float)):
        return float(b) + float(c)
    return float('-inf')

result = {}
for block in blocks:
    items = [(r, data[r]) for r in block]
    items.sort(key=lambda x: dval(x[1]), reverse=True)  # stable for ties
    for i, (orig_r, vals) in enumerate(items):
        result[block[0] + i] = vals

